import Consul from 'consul';
const consul = new Consul();

export async function getHealthyServiceEndpoint(serviceName: string): Promise<string> {
  // Query Consul registry for healthy instances only
  const instances: any = await consul.health.service({
    service: serviceName,
    passing: true, // Filters out unhealthy or flapping nodes
  });

  if (!instances || instances.length === 0) {
    throw new Error(`No healthy instances found for ${serviceName}`);
  }

  // Select random instance (client-side load balancing)
  const selected = instances[Math.floor(Math.random() * instances.length)];
  return `http://${selected.Service.Address}:${selected.Service.Port}`;
}
